svg.script:
/**/
(function() {
  var root = document.getElementById('a12p14h-svg');
  if (!root) return;

  var levelData = {
    0: {
      badge: "VISÃO GERAL DO EIXO",
      badgeColor: "var(--a12p14h-accent-pink, #e05297)",
      title: "SISTEMA TRIDIMENSIONAL INTEGRADO",
      vector: "VETOR GLOBAL: EXAMINADOR → PROXIMAL",
      vectorColor: "var(--a12p14h-cyan-vector, #00d2d3)",
      anatomy: [
        "• Polo Externo: Hímen, Vulva e Períneo (0 cm)",
        "• Plano Médio: Diafragma Pélvico (+4 cm)",
        "• Polo Interno: Vísceras Subperitoneais (+8 cm)"
      ],
      clinical: [
        "• Referência fixa universal: Plano Himenal (0)",
        "• 'Abaixo' = Sentido distal (saída vulvar / examinador)",
        "• 'Acima' = Sentido proximal (interior pélvico)"
      ],
      pointerX: 150
    },
    1: {
      badge: "POLO INTERNO (PROFUNDO)",
      badgeColor: "var(--a12p14h-green-normal, #2ecc71)",
      title: "CAMADA VISCERAL SUBPERITONEAL",
      vector: "ACIMA = MAIS PROFUNDO / INTERNO",
      vectorColor: "var(--a12p14h-green-normal, #2ecc71)",
      anatomy: [
        "• Fundo e Corpo Uterino / Fundo de Saco",
        "• Parede Superior da Bexiga Urinária",
        "• Reto Médio-Superior Subperitoneal"
      ],
      clinical: [
        "• Localização anatômica de maior distância ao examinador",
        "• No POP-Q: Valores altamente negativos (ex: -6 a -8 cm)",
        "• Ponto C (colo) e Ponto D (fundo de saco)"
      ],
      pointerX: 270
    },
    2: {
      badge: "PLANO MEDIAL (SUPORTE)",
      badgeColor: "var(--a12p14h-yellow-warning, #ffa502)",
      title: "DIAFRAGMA PÉLVICO & FASCIA",
      vector: "DIVISOR FISIOLÓGICO INTERNO/EXTERNO",
      vectorColor: "var(--a12p14h-yellow-warning, #ffa502)",
      anatomy: [
        "• m. Levantador do Ânus (Puborretal/Iliocóccigeo)",
        "• Fascia Endopélvica e Arco Tendíneo",
        "• Hiato Urogenital (Zona de transição)"
      ],
      clinical: [
        "• Plano de sustentação ativa e passiva dos órgãos",
        "• Rutura muscular permite a descida organica distal",
        "• Nível II de Lancey (Fascia endopélvica lateral)"
      ],
      pointerX: 150
    },
    3: {
      badge: "POLO EXTERNO (SUPERFICIAL)",
      badgeColor: "var(--a12p14h-red-alert, #ff4757)",
      title: "PLANO CUTÂNEO PERINEAL & EXAME",
      vector: "ABAIXO = DISTAL (MAIS PARA FORA)",
      vectorColor: "var(--a12p14h-red-alert, #ff4757)",
      anatomy: [
        "• Óstios Uretral, Vaginal (Hímen) e Anal",
        "• Corpo Perineal e Músculos Superficiais",
        "• Superfície em contato direto com o examinador"
      ],
      clinical: [
        "• Ponto de origem do vetor de exame clínico",
        "• No POP-Q: Hímen é a linha 0 cm (Marco de Referência)",
        "• Estruturas exteriorizadas recebem sinal positivo (+)"
      ],
      pointerX: 20
    }
  };

  function setLevel(lvl) {
    root.setAttribute('data-active-level', lvl);
    var data = levelData[lvl] || levelData[0];

    // Update Badge
    var badgeBox = document.getElementById('a12p14h-badge-box');
    var badgeTxt = document.getElementById('a12p14h-badge-txt');
    if (badgeBox) badgeBox.setAttribute('fill', data.badgeColor);
    if (badgeTxt) badgeTxt.textContent = data.badge;

    // Update Title & Vector
    var titleTxt = document.getElementById('a12p14h-card-title');
    var vectorTxt = document.getElementById('a12p14h-prop-vector');
    if (titleTxt) titleTxt.textContent = data.title;
    if (vectorTxt) {
      vectorTxt.textContent = data.vector;
      vectorTxt.setAttribute('fill', data.vectorColor);
    }

    // Update Anatomy List
    var a1 = document.getElementById('a12p14h-prop-anatomy-1');
    var a2 = document.getElementById('a12p14h-prop-anatomy-2');
    var a3 = document.getElementById('a12p14h-prop-anatomy-3');
    if (a1) a1.textContent = data.anatomy[0] || '';
    if (a2) a2.textContent = data.anatomy[1] || '';
    if (a3) a3.textContent = data.anatomy[2] || '';

    // Update Clinical List
    var c1 = document.getElementById('a12p14h-prop-clinical-1');
    var c2 = document.getElementById('a12p14h-prop-clinical-2');
    var c3 = document.getElementById('a12p14h-prop-clinical-3');
    if (c1) c1.textContent = data.clinical[0] || '';
    if (c2) c2.textContent = data.clinical[1] || '';
    if (c3) c3.textContent = data.clinical[2] || '';

    // Update Gauge Pointer Position
    var pointer = document.getElementById('a12p14h-gauge-pointer');
    if (pointer) {
      pointer.setAttribute('transform', 'translate(' + (data.pointerX - 150) + ', 0)');
    }
  }

  // Attach Click & Keyboard Events
  function bindBtn(id, lvl) {
    var el = document.getElementById(id);
    if (!el) return;
    var handler = function(e) {
      e.preventDefault();
      setLevel(lvl);
    };
    el.addEventListener('click', handler);
    el.addEventListener('keydown', function(e) {
      if (e.key === 'Enter' || e.key === ' ') {
        e.preventDefault();
        setLevel(lvl);
      }
    });
  }

  bindBtn('a12p14h-tab-0', 0);
  bindBtn('a12p14h-tab-1', 1);
  bindBtn('a12p14h-tab-2', 2);
  bindBtn('a12p14h-tab-3', 3);

  bindBtn('a12p14h-node-1', 1);
  bindBtn('a12p14h-node-2', 2);
  bindBtn('a12p14h-node-3', 3);

  // Default State
  setLevel(0);
})();
/**/
